const escape = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
};

const clean = (text) => {
  if (!text) return '';
  return String(text).replace(/^[-•\s\d.*)]+/gm, '').trim();
};

