const getLocalizedText = (text) => {
  if (!text) return '';
  let processed = String(text);
  processed = processed.replace(/\$\{industry\}/gi, industry)
                      .replace(/\${industry}/gi, industry)
                      .replace(/General sector/gi, industry + ' ' + t.sector)
                      .replace(/General industry/gi, industry)
                      .replace(/Your Business/gi, business)
                      .replace(/Your business/gi, business)
                      .replace(/Votre Entreprise/gi, business);
  return escape(clean(processed));
};

const renderSwotList = (items, icon, color, maxItems = null) => {
  if (!items || !items.length) {
    return `<div class="empty-state">${lang === 'fr' ? 'Aucun élément détecté' : 'None detected'}</div>`;
  }

  let limitedItems = items;
  if (maxItems && maxItems > 0) limitedItems = items.slice(0, maxItems);

  return `
    <ul class="swot-list">
      ${limitedItems.map(item => `
        <li>
          <span class="swot-icon" style="color: ${color}">${icon}</span>
          <span class="swot-text">${escape(item)}</span>
        </li>
      `).join('')}
    </ul>
  `;
};

const renderPhaseActions = (actions, phaseNumber) => {
  const actionItems = ensureArr(actions).map(item => {
    if (typeof item === 'object' && item.focus != null) return item.focus;
    if (typeof item === 'object' && item.task != null) return item.task;
    if (typeof item === 'object' && item.action != null) return item.action;
    return item;
  }).filter(item => item && String(item).length > 0);

  if (!actionItems.length) return '';

  const phaseIcons = ['🌱', '📈', '🚀'];
  const phaseIcon = phaseIcons[phaseNumber - 1] || '•';

  return `
    <div class="phase-actions">
      ${actionItems.map(item => `
        <div class="phase-action-item">
          <span class="phase-action-icon">${phaseIcon}</span>
          <span class="phase-action-text">${getLocalizedText(item)}</span>
        </div>
      `).join('')}
    </div>
  `;
};

const getScriptTitle = (index, script, industry) => {
  const baseTitle = script.title || script.type || '';
  const scriptTypes = {
    fr: ['Storytelling Impactant', 'Tutoriel Pratique', 'Étude de Cas Réelle', 'Séance Questions-Réponses', 'Guide Étape par Étape', 'Alerte Tendance Sectorielle', 'Témoignage Client Authentique', 'Comparaison Stratégique', 'Démystification Expert', 'Accès Privilégié'],
    en: ['Impactful Storytelling', 'Practical Tutorial', 'Real Case Study', 'Q&A Session', 'Step-by-Step Guide', 'Industry Trend Alert', 'Authentic Client Testimonial', 'Strategic Comparison', 'Expert Myth-Busting', 'Exclusive Access'],
    es: ['Storytelling Impactante', 'Tutorial Práctico', 'Estudio de Caso Real', 'Sesión de Preguntas y Respuestas', 'Guía Paso a Paso', 'Alerta de Tendencias del Sector', 'Testimonio Auténtico de Cliente', 'Comparación Estratégica', 'Desmitificación de Expertos', 'Acceso Exclusivo'],
    de: ['Wirkungsvolles Storytelling', 'Praktisches Tutorial', 'Echte Fallstudie', 'F&A-Sitzung', 'Schritt-für-Schritt-Anleitung', 'Branchentrend-Alarm', 'Authentisches Kunden-Testimonial', 'Strategischer Vergleich', 'Experten-Mythen-Entlarvung', 'Exklusiver Zugang']
  };

  const types = scriptTypes[lang] || scriptTypes.en;
  const type = types[index] || types[0];

  // ✅ CORRECTION : Nettoyer le titre s'il contient déjà la plateforme
  let cleanTitle = baseTitle;
  if (cleanTitle.toLowerCase().includes('instagram')) {
    cleanTitle = cleanTitle.replace(/instagram\s*instagram/gi, 'Instagram')
                          .replace(/instagram\s+reels/gi, 'Reels');
  }

  if (cleanTitle.toLowerCase().includes('general') || 
      cleanTitle.toLowerCase().includes('script') ||
      cleanTitle.toLowerCase().includes('guion') ||
      cleanTitle.toLowerCase().includes('skript') ||
      cleanTitle.length < 5) {
    return `${type} • ${industry}`;
  }

  return `${type} • ${escape(cleanTitle)}`;
};

