// NODE: Compile Final Report - VERSION AVEC FALLBACK CLIENT DATA

const c = $json;

// 1. SOURCES DE DONNÉES
let detectNode = {};
try { 
  detectNode = $('Detect Language').first().json || {}; 
} catch (e) { 
  console.log('Detect Language node not found');
}

let stripeData = {};
try { 
  stripeData = $('Stripe Webhook').item.json.body?.data?.object || {}; 
} catch (e) {
  console.log('Stripe webhook data not found');
}

const metadata = stripeData.metadata || {};

// 2. FONCTION D'EXTRACTION ROBUSTE
const getData = (metadataFields, sheetFields, defaultValue) => {
  for (const field of metadataFields) {
    const value = metadata[field];
    if (value && String(value).trim() !== '') return String(value).trim();
  }
  for (const field of sheetFields) {
    const value = c[field];
    if (value && String(value).trim() !== '') return String(value).trim();
  }
  for (const field of sheetFields) {
    const value = detectNode[field];
    if (value && String(value).trim() !== '') return String(value).trim();
  }
  return defaultValue;
};

// 3. LANGUE - LOGIQUE ROBUSTE

// Nouvelle priorité : récupérer d'abord la langue depuis "Prepare Client Data for AI"
let finalLanguage = 'en';
let languageSource = 'fallback';

try {
  const clientData = $('Prepare Client Data for AI').first().json || {};
  if (clientData.preferred_language || clientData.detected_language) {
    finalLanguage = clientData.preferred_language || clientData.detected_language || 'en';
    languageSource = 'client_data';
    console.log('✅ Language from Prepare Client Data for AI:', finalLanguage);
  }
} catch (e) {
  console.log('Prepare Client Data for AI node not found or invalid, fallback to Stripe/Detect logic');
}

// Fonction pour normaliser la langue
const normalizeLanguage = (lang) => {
  if (!lang) return null;

  const str = String(lang).toLowerCase().trim();

  const languageMap = {
    'fr': ['fr', 'french', 'français', 'francais', '🇫🇷', 'fra'],
    'en': ['en', 'english', 'anglais', '🇺🇸', '🇬🇧', 'eng'],
    'es': ['es', 'spanish', 'español', 'espanol', '🇪🇸', 'spa'],
    'de': ['de', 'german', 'deutsch', '🇩🇪', 'ger']
  };

  for (const [code, variations] of Object.entries(languageMap)) {
    if (variations.includes(str)) {
      return code;
    }
  }

  for (const [code, variations] of Object.entries(languageMap)) {
    for (const variation of variations) {
      if (str.includes(variation) && variation.length > 1) {
        return code;
      }
    }
  }

  return null;
};

// Si la langue n'a pas été trouvée via client_data, on applique la logique Stripe/Detect
const metadataLang = metadata.preferred_language;
const metadataRaw = metadata.preferred_language_raw;

console.log('=== LANGUAGE DEBUG ===');
console.log('languageSource initial:', languageSource);
console.log('metadata.preferred_language:', metadataLang);
console.log('metadata.preferred_language_raw:', metadataRaw);

// Priorité suivante : Metadata Stripe normalisée
if (languageSource === 'fallback' && metadataLang) {
  const normalized = normalizeLanguage(metadataLang);
  if (normalized) {
    finalLanguage = normalized;
    languageSource = 'stripe_metadata';
    console.log('✅ Language from metadata:', finalLanguage);
  }
}

// Si pas trouvé, essayer avec raw
if (languageSource === 'fallback' && metadataRaw) {
  const normalized = normalizeLanguage(metadataRaw);
  if (normalized) {
    finalLanguage = normalized;
    languageSource = 'stripe_metadata_raw';
    console.log('✅ Language from metadata raw:', finalLanguage);
  }
}

// Priorité suivante : Detect Node
if (languageSource === 'fallback' && detectNode.preferred_language) {
  const normalized = normalizeLanguage(detectNode.preferred_language);
  if (normalized) {
    finalLanguage = normalized;
    languageSource = 'detect_node';
    console.log('✅ Language from detect node:', finalLanguage);
  }
}

// 4. EXTRACTION DES DONNÉES CLIENT
const firstName = getData(['first_name'], ['first_name', 'firstname'], 'Client');
const businessName = getData(['business_name'], ['business_name', 'businessname'], 'Your Business');
