}

console.log('=== AI DATA COLLECTION ===');
console.log('Strategic analysis keys:', Object.keys(strategicAnalysis));
console.log('Action plan keys:', Object.keys(actionPlan90d));
console.log('Scripts count:', contentScripts.length);

// 6. CONSTRUCTION PDF DATA
