// ========================================
// PARSE SCRIPTS + BONUS FUNNEL & TOOLS
// VERSION CORRIGÉE - Gestion des erreurs robuste
// ========================================

const parent = $('Prepare Scripts').first().json;
const inputData = $input.all();
const response = (inputData && inputData.length > 0 && inputData[0]?.json) ? inputData[0].json : null;

let scripts = [];
const industry = parent.industry || 'General';
const lang = parent.preferred_language || parent.detected_language || 'en';

console.log('=== PARSE SCRIPTS + BONUS ===');
console.log('Industry:', industry);
console.log('Language:', lang);
console.log('Response present:', !!response);
if (response) {
  console.log('Response keys:', Object.keys(response));
}

try {
  // Vérifier si on a une réponse valide de l'IA
  const hasValidResponse = response && 
                          !response.error && 
                          (response.message?.content || 
                           response.choices?.[0]?.message?.content || 
                           response.content);

  if (!hasValidResponse) {
    console.log('⚠️ No valid AI response, will use fallback');
    throw new Error('Invalid or missing AI response');
  }

  // Cas où response est directement le string JSON
  let content = '';
  if (typeof response === 'string') {
    content = response;
    console.log('? Response is direct string');
  } else {
    content = response.message?.content || 
                 response.choices?.[0]?.message?.content || 
                 response.content || '';
  }

  console.log('Content length:', content.length);
  console.log('Content preview:', content.substring(0, 200));

  if (content.length < 50) {
    throw new Error('AI response too short');
  }

  // Essayer de trouver du JSON valide
  let parsed = null;
  let jsonString = '';

  // Tentative 1: Chercher du JSON entre accolades ou crochets
  const jsonMatch = content.match(/(\{[\s\S]*\})|(\[[\s\S]*\])/);
  if (jsonMatch) {
    jsonString = jsonMatch[0];
    try {
      parsed = JSON.parse(jsonString);
      console.log('✅ JSON parsed successfully from match');
    } catch (e) {
      console.log('⚠️ First JSON parse failed:', e.message);
    }
  }

  // Tentative 2: Si échec, essayer de nettoyer et parser tout le contenu
  if (!parsed) {
    try {
      const cleanContent = content
        .replace(/```json\s*/g, '')
        .replace(/```\s*/g, '')
        .replace(/^[\s\S]*?(\{|\[)/, '$1')
        .replace(/(\}|\])[\s\S]*$/, '$1');

      parsed = JSON.parse(cleanContent);
      console.log('✅ JSON parsed from cleaned content');
    } catch (e2) {
      console.log('❌ Second JSON parse failed:', e2.message);
      throw new Error('Could not parse JSON from AI response');
    }
  }

  // Extraire les scripts selon différents formats possibles
  if (Array.isArray(parsed)) {
    scripts = parsed;
    console.log('✅ Found scripts as direct array');
  } else if (parsed.scripts && Array.isArray(parsed.scripts)) {
    scripts = parsed.scripts;
    console.log('✅ Found scripts in scripts property');
  } else if (parsed.content_scripts && Array.isArray(parsed.content_scripts)) {
    scripts = parsed.content_scripts;
    console.log('✅ Found scripts in content_scripts property');
  } else {
    const arrayKeys = Object.keys(parsed).filter(k => Array.isArray(parsed[k]));
    if (arrayKeys.length > 0) {
      scripts = parsed[arrayKeys[0]];
      console.log('✅ Found scripts in array property:', arrayKeys[0]);
    } else {
      throw new Error('No scripts array found in parsed JSON');
    }
  }

  // Définir les templates multilingues AVANT la normalisation
  const normTemplates = {
    en: {
      defaultHook: (ind) => `Stop making this common ${ind} mistake`,
      defaultBody: (ind) => `Framework for ${ind} businesses`,
      defaultCTA: 'Book a call or download free guide in bio',
      defaultTitle: (ind, idx) => `High-Converting ${ind} Script ${idx + 1}`
    },
    fr: {
      defaultHook: (ind) => `Arrêtez cette erreur ${ind} courante`,
      defaultBody: (ind) => `Framework pour les entreprises ${ind}`,
      defaultCTA: 'Réservez un appel ou téléchargez le guide gratuit (lien bio)',
      defaultTitle: (ind, idx) => `Script ${ind} à Forte Conversion ${idx + 1}`
    },
    es: {
      defaultHook: (ind) => `Deja de cometer este error común en ${ind}`,
      defaultBody: (ind) => `Framework para negocios de ${ind}`,
      defaultCTA: 'Reserva una llamada o descarga la guía gratis (enlace en bio)',
      defaultTitle: (ind, idx) => `Script de Alta Conversión ${ind} ${idx + 1}`
    },
    de: {
      defaultHook: (ind) => `Stoppen Sie diesen häufigen ${ind} Fehler`,
      defaultBody: (ind) => `Framework für ${ind} Unternehmen`,
      defaultCTA: 'Buchen Sie einen Anruf oder laden Sie den kostenlosen Leitfaden herunter (Link in Bio)',
      defaultTitle: (ind, idx) => `High-Converting ${ind} Script ${idx + 1}`
    }
  };

  const nt = normTemplates[lang] || normTemplates.en;

  // Valider et normaliser chaque script
  scripts = scripts.map((script, index) => {
    if (typeof script === 'string') {
      return {
        script_number: index + 1,
        platform: 'TikTok',
        type: 'Content',
        title: `Script ${index + 1}`,
        hook: script.substring(0, 100) + '...',
        body: script,
        cta: nt.defaultCTA,
        hashtags: [`#${industry}`, '#business']
      };
    }

    return {
      script_number: index + 1,
      platform: script.platform || script.Platform || ['TikTok', 'Instagram', 'YouTube'][index % 3],
      type: script.type || script.Type || ['Contrarian', 'How-To', 'Case Study', 'Q&A'][index % 4],
