  analysis = JSON.parse(cleaned);

  // Validation de qualité
  if (!analysis.executive_summary || analysis.executive_summary.length < 200) {
    console.warn(`Executive summary too short: ${analysis.executive_summary?.length || 0} chars`);
    // Ne pas throw, on garde ce qu'on a
  }

  console.log('✅ Analysis parsed successfully from AI');

} catch (e) {
  console.error('❌ Parse failed:', e.message);
  console.log('Response structure:', JSON.stringify(response, null, 2).substring(0, 1000));

  // FALLBACK INTELLIGENT avec les VRAIES données client
  const fallbacks = {
    en: {
      executive_summary: `${businessName} operates in the ${industry} sector with a focus on ${mainObjective}. The primary challenge identified is ${mainChallenge}. This analysis provides strategic recommendations tailored to their specific situation, considering their team size and market position. The following SWOT analysis highlights key areas for improvement and growth opportunities.`,
      swot_analysis: {
        strengths: [
          `Positioned in growing ${industry} market`,
          `Clear objective: ${mainObjective}`,
          `Dedicated team committed to growth`
        ],
        weaknesses: [
          `Challenge to address: ${mainChallenge}`,
          `Resource constraints typical for ${industry}`
        ],
        opportunities: [
          `Market expansion in ${industry}`,
          `Digital transformation opportunities`,
          `Customer acquisition strategies`
        ],
        threats: [
          `Competitive pressure in ${industry}`,
          `Market volatility`
        ]
      },
      target_audience: {
        primary_persona: `Target customers in the ${industry} sector`,
        pain_points: [`Specific challenges related to ${mainChallenge}`]
      }
    },
    fr: {
      executive_summary: `${businessName} opère dans le secteur ${industry} avec un focus sur ${mainObjective}. Le défi principal identifié est ${mainChallenge}. Cette analyse fournit des recommandations stratégiques adaptées à leur situation spécifique, tenant compte de la taille de leur équipe et de leur positionnement marché. L'analyse SWOT suivante met en lumière les principaux domaines d'amélioration et les opportunités de croissance.`,
      swot_analysis: {
        strengths: [
          `Positionné sur le marché ${industry} en croissance`,
          `Objectif clair : ${mainObjective}`,
          `Équipe dédiée et engagée`
        ],
        weaknesses: [
          `Défi à surmonter : ${mainChallenge}`,
          `Contraintes de ressources typiques pour ${industry}`
        ],
        opportunities: [
          `Expansion du marché ${industry}`,
          `Opportunités de transformation digitale`,
          `Stratégies d'acquisition client`
        ],
        threats: [
          `Pression concurrentielle dans ${industry}`,
          `Volatilité du marché`
        ]
      },
      target_audience: {
        primary_persona: `Clients cibles dans le secteur ${industry}`,
        pain_points: [`Défis spécifiques liés à ${mainChallenge}`]
      }
    }
    // Ajouter es et de si nécessaire
  };

  // Utiliser le fallback approprié selon la langue
  analysis = fallbacks[lang] || fallbacks.en;
  analysis.fallback_used = true;
  analysis.fallback_reason = e.message;

  console.log(`Created ${lang} fallback analysis for ${businessName}`);
}

// Retourner avec TOUTES les données parent
return [{
  json: {
    ...parent, // Garder TOUTES les données du parent
    strategic_analysis: analysis,
    parsing_success: !analysis.fallback_used,
    analysis_quality: {
      summary_length: analysis.executive_summary?.length || 0,
      strengths_count: analysis.swot_analysis?.strengths?.length || 0,
      fallback_used: !!analysis.fallback_used,
      language_used: lang
    }
  }
}];

// NODE: Prepare AI Analysis - VERSION CORRIGÉE AVEC RÉCUPÉRATION EXPLICITE
// Le node précédent est "Send email" qui ne contient PAS les données client
// Il faut récupérer les données du node "Prepare Client Data for AI" ou "Map Fillout Fields"

let client = null;

// ESSAYER DE RÉCUPÉRER LES DONNÉES DU BON NODE
try {
  // Priorité 1: Node "Prepare Client Data for AI" (source principale)
  client = $('Prepare Client Data for AI').first().json;
  console.log('✅ Using Prepare Client Data for AI');
} catch (e1) {
  console.log('⚠️ Prepare Client Data for AI failed:', e1.message);

  try {
    // Priorité 2: Node "Map Fillout Fields to Clean Data"
    client = $('Map Fillout Fields to Clean Data').first().json;
    console.log('✅ Using Map Fillout Fields to Clean Data');
  } catch (e2) {
    console.log('⚠️ Map Fillout Fields failed:', e2.message);

    try {
      // Priorité 3: Fallback sur l'input actuel (au cas où)
      if ($input && $input.item && $input.item.json) {
        client = $input.item.json;
        console.log('✅ Using $input.item.json');
      } else {
        throw new Error('No input data');
      }
    } catch (e3) {
      console.error('❌ CRITICAL: Could not retrieve client data from any source');
      throw new Error('Missing client data - check workflow connections');
    }
  }
}

// DEBUG
console.log('=== PREPARE AI ANALYSIS - CLIENT DATA ===');
console.log('Client:', JSON.stringify(client, null, 2));
console.log('first_name:', client?.first_name);
console.log('email:', client?.email);
console.log('business_name:', client?.business_name);
console.log('main_challenge:', client?.main_challenge);

// VALIDATION
if (!client.first_name || !client.email) {
  console.error('❌ Missing required fields:', {
    has_first_name: !!client.first_name,
    has_email: !!client.email
  });
  throw new Error(`Missing required client data: first_name or email`);
}

// EXTRACT DATA
const firstName = client.first_name;
const businessName = client.business_name;
const industry = client.industry || 'General';
const mainObjective = client.main_objective || 'Business growth';
const mainChallenge = client.main_challenge || 'Growth challenges';
const monthlyRevenue = client.monthly_revenue || 'Not specified';
const marketingBudget = client.marketing_budget || 'Not specified';
const teamSize = client.team_size || 'Not specified';
const website = client.website || '';
const lang = client.preferred_language || client.detected_language || 'en';

console.log(`🎯 Preparing AI analysis for ${firstName} at ${businessName}`);
console.log(`📊 Industry: ${industry} | Objective: ${mainObjective} | Challenge: ${mainChallenge}`);
console.log(`🌐 Language: ${lang}`);

// LANGUAGE CONFIG
const languageConfig = {
  en: { name: 'ENGLISH', tone: 'professional and actionable' },
  fr: { name: 'FRENCH', tone: 'professionnel et actionnable' },
  es: { name: 'SPANISH', tone: 'profesional y práctico' },
  de: { name: 'GERMAN', tone: 'professionell und umsetzbar' }
};

const langCfg = languageConfig[lang] || languageConfig.en;

// PROMPT
const PROMPT_ANALYSIS = `You are an elite marketing strategist specializing in ${industry}.

CRITICAL CLIENT CONTEXT:
• Business Name: "${businessName}"
• Industry: ${industry}
• Team Size: ${teamSize}
• Monthly Revenue: ${monthlyRevenue}
• Marketing Budget: ${marketingBudget}
• PRIMARY GOAL: "${mainObjective}"
• BIGGEST CHALLENGE: "${mainChallenge}"
${website ? `• Website: ${website}` : ''}

YOUR MISSION:
Create a hyper-personalized strategic analysis for "${businessName}" in the ${industry} industry.

REQUIREMENTS:
1. Executive Summary: 350-450 words analyzing "${businessName}" specifically
2. SWOT Analysis: Each point must reference "${businessName}", "${industry}", or "${mainChallenge}"
3. Language: ${langCfg.name} only

STRICT JSON FORMAT:
{
  "executive_summary": "Detailed analysis for ${businessName}...",
  "swot_analysis": {
    "strengths": ["..."],
    "weaknesses": ["..."],
    "opportunities": ["..."],
    "threats": ["..."]
  },
  "target_audience": {
    "primary_persona": "...",
    "pain_points": ["..."]
  }
}

Respond ONLY with valid JSON.`;

// RETURN
return {
  json: {
    ...client, // Garde toutes les données originales
    ai_config_analysis: {
      model: 'llama-3.3-70b-versatile',
      messages: [
        {
          role: 'system',
          content: `You are a top-tier marketing consultant. Write in ${langCfg.name} only.`
        },
        {
          role: 'user',
          content: PROMPT_ANALYSIS
        }
      ],
      temperature: 0.5,
      max_tokens: 4500,
      top_p: 0.85,
      response_format: { type: "json_object" }
    },
    analysis_context: {
      business_name: businessName,
      industry: industry,
      main_objective: mainObjective,
      main_challenge: mainChallenge,
      language: lang
    },
    prepared_at: new Date().toISOString()
  }
};

// CHECK AI INPUTS - validate required fields before calling AI
const c = $json;
const detect = c.detected_language || c.preferred_language || ($node['Detect Language'] ? $node['Detect Language'].json.detected_language : null);
if (!detect) { throw new Error('Missing detected_language or preferred_language'); }
if (!c.client_data && !(c.email || c.business_name)) { throw new Error('Missing client data (email or business_name)'); }
console.log('AI inputs OK - language:', detect);
return [{ json: { ...c, validated_for_ai: true } }];

const headers = $json.headers || {};
const signature = headers['stripe-signature'] || headers['Stripe-Signature'];

if (!signature) {
  throw new Error('Stripe signature missing');
}

return {
  json: {
    payment_verified: true,
    signature_present: true,
    verified_at: new Date().toISOString()
  }
};

const data = $json;

// 1. FILTER STRIPE EVENTS (Prevent Double Execution)
// Stripe sends multiple webhooks (payment_intent.created, charge.succeeded, etc.)
// We only want to trigger the delivery on checkout.session.completed
const rawBody = $node["Stripe Webhook"].json.body || {};
const eventType = rawBody.type || "unknown";

if (eventType !== 'checkout.session.completed') {
  return {
    json: {
      stop_workflow: true,
      reason: `Ignored event type: ${eventType}`
    }
  };
}

// 2. CHECK IF ALREADY GENERATED (Prevent Duplicate Delivery)
const alreadyGenerated = data.audit_generated === true || data.audit_generated === 'Yes' || data.audit_generated === 'true';

if (alreadyGenerated) {
  return {
    json: {
      stop_workflow: true,
      reason: 'Audit already generated/delivered for this customer',
      checked_at: new Date().toISOString()
    }
  };
}

// 3. VALIDATE PAYMENT STATUS
const paymentStatus = rawBody.data?.object?.payment_status || "unprocessed";

if (paymentStatus !== 'paid') {
  return {
    json: {
      stop_workflow: true,
      reason: `Payment status is ${paymentStatus}, expected 'paid'`
    }
  };
}

// 4. ALL OK - PROCEED
return {
  json: {
    stop_workflow: false,
    payment_verified: true,
    event_type: eventType,
    checked_at: new Date().toISOString()
  }
};

// GENERATE EMAIL CONTENT - MULTILINGUE COMPLET
// VERSION CORRIGÉE : Extraction des données réelles depuis pdf_data

// ========================================
// 1. RÉCUPÉRATION ROBUSTE DES DONNÉES
// ========================================

let sourceData = null;
let pdfData = null;
let dataSource = 'unknown';
let binaryData = null;

console.log('=== GENERATE EMAIL CONTENT - DEBUG ===');

// Priorité 1: Get Download URL (contient les infos PDF + données client)
try {
  const downloadUrlData = $('Get Download URL').first().json;
  if (downloadUrlData) {
    sourceData = downloadUrlData;
    pdfData = downloadUrlData.pdf_data || downloadUrlData;
    dataSource = 'get_download_url';

    // Essayer de récupérer le binary depuis Prepare HTML Report
    try {
      binaryData = $('Prepare HTML Report').first().binary;
      if (binaryData) console.log('✅ Binary from Prepare HTML Report');
    } catch (e) {
      console.log('⚠️ No binary from Prepare HTML Report');
    }

    console.log('✅ Source: Get Download URL');
  }
} catch (e1) {
  console.log('⚠️ Cannot access Get Download URL:', e1.message);
}

// Priorité 2: Compile Final Report (contient pdf_data complet)
if (!sourceData || !pdfData) {
  try {
    const compiledData = $('Compile Final Report').first().json;
    if (compiledData && compiledData.pdf_data) {
      sourceData = compiledData;
      pdfData = compiledData.pdf_data;
      dataSource = 'compile_final_report';
      console.log('✅ Source: Compile Final Report > pdf_data');
    }
  } catch (e2) {
    console.log('⚠️ Cannot access Compile Final Report:', e2.message);
  }
}

// Priorité 3: Input direct
if (!sourceData || !pdfData) {
  try {
    const inputData = $input.first().json;
    if (inputData) {
      sourceData = inputData;
      pdfData = inputData.pdf_data || inputData;
      dataSource = 'input_data';
      console.log('✅ Source: $input');
    }
  } catch (e3) {
    console.log('❌ CRITICAL: No data available');
    throw new Error('Missing client data for email generation');
  }
}

// DEBUG: Afficher ce qu'on a trouvé
console.log('=== EXTRACTED DATA ===');
console.log('Data source:', dataSource);
console.log('pdfData keys:', Object.keys(pdfData));
console.log('Has binary?', !!binaryData);

// ========================================
// 2. EXTRACTION DES DONNÉES CLIENT RÉELLES
// ========================================

// 1. On récupère d'abord les données brutes du formulaire (Source la plus fiable pour l'industrie)
let rawClientData = {};
try {
  rawClientData = $('Map Fillout Fields to Clean Data').first().json;
} catch (e) {
  console.log('⚠️ Could not access Map Fillout Fields');
}

// 2. Extraction du prénom
const firstName = pdfData.first_name || pdfData.firstname || rawClientData.first_name || 'Client';

// 3. Extraction du nom de l'entreprise
const businessName = pdfData.business_name || pdfData.businessname || rawClientData.business_name || 'Votre Entreprise';

const email = rawClientData.email || pdfData.email || '';
// 4. Extraction de l'INDUSTRIE (Correction ici)
const industry = pdfData.industry || 
                 rawClientData.industry || 
                 sourceData.industry || 
                 'votre secteur';

// 5. Extraction de la LANGUE
let lang = 'en';
try { 
  lang = rawClientData.preferred_language || pdfData.language || 'en'; 
} catch (e) {}
if (!['en','fr','es','de'].includes(lang)) lang = 'en';


// URL du PDF - depuis Get Download URL ou autre source
const pdfUrl = sourceData.pdfdownloadurl || 
              sourceData.pdf_download_url || 
              (dataSource === 'get_download_url' ? sourceData.pdfdownloadurl : null) ||
              '#';

// ========================================
// 3. VALIDATION DES DONNÉES
// ========================================

console.log('🎯 CLIENT DATA FOR EMAIL:');
console.log('  First Name:', firstName, firstName !== 'Client' ? '✓ REAL' : '⚠ GENERIC');
console.log('  Business:', businessName, !businessName.includes('Your Business') ? '✓ REAL' : '⚠ GENERIC');
console.log('  Email:', email ? '✓ PRESENT' : '⚠ MISSING');
console.log('  Industry:', industry);
console.log('  Language:', lang);
console.log('  PDF URL:', pdfUrl !== '#' ? '✓ PRESENT' : '⚠ MISSING');
console.log('  Data Source:', dataSource);

// Vérifier qu'on a les données minimales
if (email === '') {
  console.warn('⚠️ WARNING: No email address found for sending');
}

// ========================================
// 4. CONTENU MULTILINGUE COMPLET
// ========================================

const i18n = {
  en: {
    subject: `Your Premium Marketing Audit: ${businessName}`,
    title: "MISSION<br><span style='color:#10b981'>ACCOMPLISHED.</span>",
    greeting: `Hello ${firstName},`,
    message: `Your comprehensive marketing audit for <strong>${businessName}</strong> is ready for review.`,
    btn: "DOWNLOAD YOUR AUDIT →",
    validity: "Secure link valid for 30 days",
    inside: "INSIDE YOUR REPORT:",
    items: [
      `<strong>Strategic Analysis:</strong> Your current market positioning in ${industry}`,
      `<strong>90-Day Plan:</strong> Step-by-step execution roadmap`,
      `<strong>Content Pack:</strong> 10 tailored viral video scripts for ${industry}`,
      `<strong>Tech Stack:</strong> The exact tools for your success`
    ],
    footer: "© 2026 Nexus Creator • Precision Marketing<br>Need help? Reply to this email."
  },
  fr: {
    subject: `Votre Audit Marketing : ${businessName}`,
    title: "MISSION<br><span style='color:#10b981'>ACCOMPLIE.</span>",
    greeting: `Bonjour ${firstName},`,
    message: `Votre audit marketing complet pour <strong>${businessName}</strong> est prêt pour analyse.`,
    btn: "TÉLÉCHARGER VOTRE AUDIT →",
    validity: "Lien sécurisé valide 30 jours",
    inside: "DANS VOTRE RAPPORT :",
    items: [
      `<strong>Analyse Stratégique :</strong> Votre positionnement marché actuel dans le secteur ${industry}`,
      `<strong>Plan 90 Jours :</strong> Votre feuille de route d'exécution`,
      `<strong>Pack Contenu :</strong> 10 scripts vidéo viraux sur mesure pour le secteur ${industry}`,
      `<strong>Tech Stack :</strong> Les outils exacts pour réussir dans le secteur ${industry}`
    ],
    footer: "© 2026 Nexus Creator • Marketing de Précision<br>Besoin d'aide ? Répondez à cet email."
  },
  es: {
    subject: `Su Auditoría de Marketing Premium: ${businessName}`,
    title: "MISIÓN<br><span style='color:#10b981'>CUMPLIDA.</span>",
    greeting: `Hola ${firstName},`,
    message: `Su auditoría de marketing completa para <strong>${businessName}</strong> está lista para revisión.`,
    btn: "DESCARGAR SU AUDITORÍA →",
    validity: "Enlace seguro válido por 30 jours",
    inside: "DENTRO DE SU INFORME:",
    items: [
      `<strong>Análisis Estratégico:</strong> Su posicionamiento actual en el mercado de ${industry}`,
      `<strong>Plan de 90 Días:</strong> Hoja de ruta de ejecución paso a paso`,
      `<strong>Pack de Contenido:</strong> 10 guiones de video virales personalizados para ${industry}`,
      `<strong>Tech Stack:</strong> Las herramientas exactas para su éxito`
    ],
    footer: "© 2026 Nexus Creator • Marketing de Precisión<br>¿Necesita ayuda? Responda a este correo."
  },
  de: {
    subject: `Ihre Premium-Marketing-Audit: ${businessName}`,
    title: "MISSION<br><span style='color:#10b981'>ERFÜLLT.</span>",
    greeting: `Hallo ${firstName},`,
    message: `Ihr umfassendes Marketing-Audit für <strong>${businessName}</strong> ist zur Überprüfung bereit.`,
    btn: "IHRE AUDIT HERUNTERLADEN →",
    validity: "Sicherer Link 30 Tage gültig",
    inside: "IN IHREM BERICHT:",
    items: [
      `<strong>Strategische Analyse:</strong> Ihre aktuelle Marktpositionierung in ${industry}`,
      `<strong>90-Tage-Plan:</strong> Schritt-für-Schritt-Umsetzungsfahrplan`,
      `<strong>Content-Paket:</strong> 10 maßgeschneiderte virale Video-Skripte für ${industry}`,
      `<strong>Tech Stack:</strong> Die genauen Tools für Ihren Erfolg`
    ],
    footer: "© 2026 Nexus Creator • Präzisionsmarketing<br>Brauchen Sie Hilfe? Antworten Sie auf diese E-Mail."
  }
};

const t = i18n[lang] || i18n.en;

const emailsubject = t.subject;

// Fonction d'échappement pour HTML
const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
};

// ========================================
// 5. CONSTRUCTION DU HTML EMAIL
// ========================================

const emailhtml = `<!DOCTYPE html>
<html lang="${lang}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(t.subject)}</title>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;700;800&family=Outfit:wght@600&display=swap');
    body { margin: 0; padding: 0; font-family: 'Inter', Helvetica, Arial, sans-serif; background-color: #0f172a; color: #f8fafc; }
    .container { max-width: 600px; margin: 0 auto; background-color: #0f172a; }
    .header { padding: 40px 30px; text-align: left; }
    .brand { color: #10b981; font-family: 'Outfit', sans-serif; font-weight: 800; font-size: 14px; letter-spacing: 3px; }
    .hero { padding: 0 30px 40px 30px; }
    .hero-title { font-size: 28px; font-weight: 800; line-height: 1.2; margin: 0 0 20px 0; color: #ffffff; }
    .glass-card { background: rgba(30, 41, 59, 0.5); border: 1px solid rgba(16, 185, 129, 0.2); border-radius: 20px; padding: 30px; margin: 0 30px 30px 30px; }
    .btn { display: inline-block; background-color: #10b981; color: #ffffff; text-decoration: none; padding: 18px 35px; border-radius: 12px; font-weight: 800; font-size: 16px; margin-top: 10px; text-align: center; box-shadow: 0 4px 15px rgba(16, 185, 129, 0.3); width: 100%; box-sizing: border-box; }
    .feature { margin-bottom: 12px; font-size: 14px; color: #cbd5e1; }
    .feature span { color: #10b981; margin-right: 10px; font-weight: bold; }
    .footer { padding: 40px 30px; text-align: center; border-top: 1px solid rgba(255, 255, 255, 0.05); }
    .footer-text { font-size: 11px; color: #475569; }
  </style>
</head>
<body>
  <table width="100%" cellpadding="0" cellspacing="0">
    <tr>
      <td align="center">
        <table width="600" class="container">
          <tr><td class="header"><div class="brand">NEXUS // CREATOR</div></td></tr>
          <tr>
            <td class="hero">
              <h1 class="hero-title">${t.title}</h1>
              <p style="color:#94a3b8; font-size:16px; line-height:1.6;">${t.greeting} ${t.message}</p>
            </td>
          </tr>
          <tr>
            <td>
              <div class="glass-card">
                <p style="color:#fff; font-weight:700; margin-top:0; font-size:14px; text-transform:uppercase; letter-spacing:1px;">${t.inside}</p>
                <div style="margin:20px 0;">
                  ${t.items.map(item => `<div class="feature"><span>✓</span> ${item}</div>`).join('')}
                </div>
                <div style="text-align:center; margin-top:30px;">
                  <a href="${escapeHtml(pdfUrl)}" class="btn">${t.btn}</a>
                  <p style="color:#64748b; font-size:11px; margin-top:15px;">${t.validity}</p>
                </div>
              </div>
            </td>
          </tr>
          <tr>
            <td class="footer">
              <p class="footer-text">${t.footer}</p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

console.log('✅ Email HTML generated successfully');
console.log(`📧 Subject: ${emailsubject}`);
console.log(`👤 Recipient: ${email || 'NO EMAIL FOUND!'}`);
console.log(`🌐 Language: ${lang}`);

// ========================================
// 6. PRÉPARATION DU RETOUR
// ========================================

// On utilise la variable binaryData déjà récupérée au début du script
let finalBinary = binaryData; 

if (!finalBinary) {
  try {
    // Fallback de sécurité si non trouvé au début
    finalBinary = $('Prepare HTML Report').first().binary;
  } catch (e) {
    console.log('⚠️ No binary PDF found for attachment');
  }
}

const result = {
  json: {
    ...sourceData,
    emailsubject: emailsubject,
    emailhtml: emailhtml,
    email_language: lang,
    generated_at: new Date().toISOString(),
    recipient: email,

    client_info: {
      first_name: firstName,
      business_name: businessName,
      email: email,
      industry: industry,
      language: lang
    },

    debug_info: {
      data_source: dataSource,
      pdf_url_present: pdfUrl !== '#',
      has_binary_attachment: !!finalBinary,
      timestamp: new Date().toISOString()
    }
  }
};

// Vérification de la structure binaire pour n8n
if (finalBinary && (finalBinary.data || finalBinary.data === "")) {
  // On s'assure que le binaire est passé avec une clé nommée (souvent 'data')
  result.binary = { data: finalBinary.data || finalBinary }; 
  console.log('✅ PDF binary attached for email');
}
else {
  console.log('⚠️ No PDF binary attached - client will get download link only');
}

return [result];

