parameters.jsCode:
const c = $json;

// Use the file id from the Create file node (safe even if this node runs after the permission node)
const fileId = $node['Create Shareable Link (30 days)']?.json?.id || c.id || null;
// URL de téléchargement DIRECT (pas la preview HTML) : le bouton doit télécharger le PDF, pas ouvrir une page
const downloadUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;

return [{
  json: {
    ...c,
    pdffileid: fileId,
    pdfdownloadurl: downloadUrl,
    pdfexpirationdate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
    pdfsentat: new Date().toISOString()
  }
}];

// DEBUG LANGUAGE DETECTION
const input = $input.first().json;

console.log('=== LANGUAGE DEBUG ===');
console.log('Preferred language:', input.preferred_language);
console.log('Detected language:', input.detected_language);
console.log('Country code:', input.country_code);
console.log('Business name:', input.business_name);
console.log('Email language source:', input.language_source);

// Afficher la langue finale qui sera utilisée
const finalLang = input.preferred_language || input.detected_language || 'en';
console.log('Final language to use:', finalLang);

return [{ json: input }];

// DEBUG GOTENBERG INPUT
const input = $input.first();

console.log('=== GOTENBERG DEBUG ===');
console.log('Input JSON keys:', Object.keys(input.json));
console.log('Has binary data?', !!input.binary?.data);

if (input.binary?.data) {
  console.log('Binary fileName:', input.binary.data.fileName);
  console.log('Binary mimeType:', input.binary.data.mimeType);
  console.log('Binary data type:', typeof input.binary.data.data);
  console.log('Binary data length (base64):', input.binary.data.data.length);

  // Vérifier que le nom est correct
  if (input.binary.data.fileName !== 'index.html') {
    console.warn('⚠️ WARNING: File name should be "index.html" for Gotenberg');
    // Corriger automatiquement
    input.binary.data.fileName = 'index.html';
    console.log('✅ File name corrected to "index.html"');
  }
}

if (input.json.html) {
  console.log('HTML content length:', input.json.html.length);
  // Afficher un preview
  const preview = input.json.html.substring(0, 200);
  console.log('HTML preview:', preview.replace(/\n/g, ' '));
}

console.log('=== END DEBUG ===');

return input;

// NODE: Map Fillout Fields to Clean Data - VERSION CORRIGÉE
const stripeData = $("Stripe Webhook").item.json.body?.data?.object || {};
const metadata = stripeData.metadata || {};
const sheetData = $input.item.json || {};

const extractField = (fieldNames, defaultValue = "Not specified") => {
  for (const name of fieldNames) {
    if (sheetData[name] && String(sheetData[name]).trim() !== "" && sheetData[name] !== "Not specified" && sheetData[name] !== "General") {
      return String(sheetData[name]).trim();
    }
  }
  for (const name of fieldNames) {
    if (metadata[name] && String(metadata[name]).trim() !== "") {
      return String(metadata[name]).trim();
    }
  }
  return defaultValue;
};

const firstName = extractField(["first_name", "firstName"], stripeData.customer_details?.name?.split(" ")[0] || "Client");
const businessName = extractField(["business_name", "businessName"], "Your Business");
const email = extractField(["email"], sheetData.email || stripeData.customer_details?.email || "");
const industry = extractField(["industry"], "General");
const mainObjective = extractField(["main_objective", "mainObjective"], "Business growth");
const mainChallenge = extractField(["main_challenge", "mainChallenge", "biggest_challenge"], "Not specified");
const monthlyRevenue = extractField(["monthly_revenue"], "Not specified");
const marketingBudget = extractField(["marketing_budget"], "Not specified");
const companySize = extractField(["company_size", "team_size"], "Not specified");

const lang = extractField(["preferred_language", "detected_language"], "en");

return {
  json: {
    first_name: firstName,
    email: email,
    business_name: businessName,
    industry: industry,
    team_size: companySize,
    monthly_revenue: monthlyRevenue,
    marketing_budget: marketingBudget,
    main_objective: mainObjective,
    main_challenge: mainChallenge,
    preferred_language: lang,
    detected_language: lang,
    stripe_session_id: stripeData.id,
    sheet_row_id: sheetData.id,
    data_source: sheetData.id ? "merged_sheet_stripe" : "stripe_only",
    processed_at: new Date().toISOString()
  }
};

// NODE: Log Quality Metrics - VERSION COMPLÈTE

const c = $json;
const pdfData = c.pdf_data || {};

// Récupération avec sécurité
const get = (obj, path, defaultVal) => {
  return path.split('.').reduce((acc, part) => acc && acc[part], obj) || defaultVal;
};

// MÉTRIQUES DE QUALITÉ
const metrics = {
  execution_id: $execution.id,
  timestamp: new Date().toISOString(),

  // Données client
  business_name: pdfData.business_name,
  industry: pdfData.industry,
  language: pdfData.preferred_language,

  // Qualité données entrée
  input_quality: {
    has_main_objective: pdfData.main_objective && pdfData.main_objective !== 'Not specified',
    has_main_challenge: pdfData.main_challenge && pdfData.main_challenge !== 'Not specified', // ✅ CRITIQUE
    has_industry: pdfData.industry && pdfData.industry !== 'General',
    has_revenue_data: pdfData.monthly_revenue && pdfData.monthly_revenue !== 'Not specified'
  },

  // Qualité génération
  analysis: {
    summary_length: get(pdfData, 'strategic_analysis.executive_summary', '').length,
    strengths_count: get(pdfData, 'strategic_analysis.swot_analysis.strengths', []).length,
    has_target_audience: !!get(pdfData, 'strategic_analysis.target_audience.primary_persona')
  },

  scripts: {
    count: (pdfData.content_scripts || []).length,
    language_consistency: pdfData.preferred_language
  },

  // Score global (0-100)
  calculate_score: function() {
    let score = 0;
    if (this.input_quality.has_main_objective) score += 15;
    if (this.input_quality.has_main_challenge) score += 15; // ✅ 15 points pour main_challenge
    if (this.input_quality.has_industry) score += 10;
    if (this.analysis.summary_length > 300) score += 20;
    if (this.analysis.strengths_count >= 3) score += 20;
    if (this.scripts.count === 10) score += 20;
    return score;
  }
};

metrics.quality_score = metrics.calculate_score();

// ALERTE SI SCORE FAIBLE
if (metrics.quality_score < 60) {
  console.error('⚠️ LOW QUALITY ALERT:', metrics.quality_score, '/100');
  console.error('Missing:', Object.entries(metrics.input_quality)
    .filter(([k,v]) => !v)
    .map(([k]) => k));
}

console.log('=== QUALITY METRICS ===');
console.log('Score:', metrics.quality_score, '/100');
console.log('Main Challenge:', pdfData.main_challenge); // ✅ VÉRIFICATION

return [{
  json: metrics
}];

// NODE: Prepare Client Data for AI
const cleanData = $json; // Données de "Map Fillout Fields"

// Vérifier que nous avons les données minimales
if (!cleanData.first_name || !cleanData.email) {
  throw new Error('Missing required client data: first_name or email');
}

// Préparer l'objet client complet
const clientData = {
  // Identité
  first_name: cleanData.first_name,
  email: cleanData.email,

  // Business
  business_name: cleanData.business_name,
  industry: cleanData.industry,
  website: cleanData.website || '',

  // Metrics
  team_size: cleanData.team_size,
  monthly_revenue: cleanData.monthly_revenue,
  marketing_budget: cleanData.marketing_budget,

  // Goals
  main_objective: cleanData.main_objective,
  main_challenge: cleanData.main_challenge,

  // Language (CRITICAL)
  preferred_language: cleanData.preferred_language,
  detected_language: cleanData.detected_language,

  // Stripe
  stripe_session_id: cleanData.stripe_session_id,
  payment_amount: cleanData.amount_paid_cents ? (cleanData.amount_paid_cents / 100) : 0,

  // Validation
  validated: true,
  validation_timestamp: new Date().toISOString()
};

console.log('✅ Client data prepared for AI:', {
  name: clientData.first_name,
  business: clientData.business_name,
  industry: clientData.industry,
  language: clientData.preferred_language,
  email: clientData.email ? '✓' : '✗'
});

return { json: clientData };

// SEND EMAIL - CONFIRMATION DE PAIEMENT MULTILINGUE (CORRIGÉ)
const c = $json;

// RÉCUPÉRATION DES DONNÉES - SOURCES MULTIPLES
